// Shared, progressively enhanced select controls. The native select retains form data/validation.
(function(){
 const registry=new Map();let serial=0;
 function labelFor(s){return s.getAttribute('aria-label')||[...s.labels??[]].map(l=>[...l.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('')).join(' ').trim()||s.name||'选择';}
 function sync(s){const r=registry.get(s);if(!r)return;const text=s.selectedOptions[0]?.textContent??'请选择';if(r.text.textContent!==text)r.text.textContent=text;r.trigger.disabled=s.disabled;r.trigger.setAttribute('aria-label',labelFor(s)+'：'+text);r.trigger.setAttribute('aria-invalid',String(!s.validity.valid));}
 function close(r,focus=false){if(r.menu.matches(':popover-open'))r.menu.hidePopover();r.trigger.setAttribute('aria-expanded','false');if(focus)r.trigger.focus({preventScroll:true});}
 function position(r){const rect=r.trigger.getBoundingClientRect(),h=r.menu.getBoundingClientRect().height;r.menu.style.left=Math.max(8,Math.min(rect.left,innerWidth-r.menu.offsetWidth-8))+'px';r.menu.style.top=(innerHeight-rect.bottom>=Math.min(h,230)?rect.bottom+6:Math.max(8,rect.top-h-6))+'px';}
 function open(s,r){if(s.disabled)return;r.menu.replaceChildren();for(const [index,o] of [...s.options].entries()){const b=document.createElement('button');b.type='button';b.role='option';b.className='select-option';b.dataset.index=index;b.disabled=o.disabled;b.setAttribute('aria-selected',String(o.selected));const t=document.createElement('span');t.textContent=o.label;b.append(t);const check=document.createElement('span');check.textContent=o.selected?'✓':'';check.setAttribute('aria-hidden','true');b.append(check);b.onclick=e=>{e.preventDefault();s.selectedIndex=index;sync(s);close(r,true);s.dispatchEvent(new Event('input',{bubbles:true}));s.dispatchEvent(new Event('change',{bubbles:true}));};r.menu.append(b);}
 const rect=r.trigger.getBoundingClientRect();r.menu.style.width=Math.max(rect.width,160)+'px';r.menu.showPopover();position(r);r.trigger.setAttribute('aria-expanded','true');(r.menu.querySelector('[aria-selected=true]:not(:disabled)')||r.menu.querySelector('button:not(:disabled)'))?.focus({preventScroll:true});}
 function enhance(root=document){for(const s of root.querySelectorAll('select:not([multiple])')){if(registry.has(s))continue;const wrapper=document.createElement('span');wrapper.className='select-control';s.before(wrapper);wrapper.append(s);s.classList.add('native-select');s.tabIndex=-1;s.setAttribute('aria-hidden','true');const trigger=document.createElement('button');trigger.type='button';trigger.className='select-trigger';trigger.role='combobox';trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');const text=document.createElement('span');const arrow=document.createElement('span');arrow.textContent='⌄';arrow.className='select-arrow';arrow.setAttribute('aria-hidden','true');trigger.append(text,arrow);const menu=document.createElement('div');menu.className='select-menu';menu.id='select-menu-'+(++serial);menu.setAttribute('popover','auto');menu.role='listbox';menu.setAttribute('aria-label',labelFor(s));trigger.setAttribute('aria-controls',menu.id);wrapper.append(trigger,menu);const r={trigger,text,menu};registry.set(s,r);sync(s);trigger.onclick=e=>{e.preventDefault();menu.matches(':popover-open')?close(r):open(s,r)};trigger.onkeydown=e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();open(s,r);if(e.key==='Home')menu.querySelector('button:not(:disabled)')?.focus({preventScroll:true});if(e.key==='End')[...menu.querySelectorAll('button:not(:disabled)')].at(-1)?.focus({preventScroll:true});}};let search='',timer;menu.onkeydown=e=>{const opts=[...menu.querySelectorAll('button:not(:disabled)')],index=opts.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?opts.length-1:(index+(e.key==='ArrowDown'?1:-1)+opts.length)%opts.length;opts[next]?.focus({preventScroll:true});}else if(e.key==='Escape'){e.preventDefault();close(r,true)}else if(e.key==='Tab'){close(r);trigger.focus()}else if(e.key.length===1&&!e.ctrlKey&&!e.metaKey){clearTimeout(timer);search+=e.key.toLocaleLowerCase();opts.find(b=>b.textContent.toLocaleLowerCase().startsWith(search))?.focus({preventScroll:true});timer=setTimeout(()=>search='',700);}};menu.addEventListener('toggle',e=>trigger.setAttribute('aria-expanded',String(e.newState==='open')));s.addEventListener('change',()=>sync(s));s.addEventListener('invalid',e=>{e.preventDefault();trigger.focus({preventScroll:true});trigger.setAttribute('aria-invalid','true')});s.form?.addEventListener('reset',()=>setTimeout(()=>sync(s),0));}}
 function refresh(){enhance();for(const [s,r] of registry){if(!s.isConnected){close(r);registry.delete(s)}else sync(s)}}
 new MutationObserver(()=>refresh()).observe(document.documentElement,{childList:true,subtree:true});addEventListener('resize',()=>{for(const r of registry.values())close(r)});document.addEventListener('scroll',e=>{for(const r of registry.values())if(r.menu.matches(':popover-open')&&!r.menu.contains(e.target))position(r)},true);window.schedulerControls={refresh};refresh();
})();
